function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Need([bool]$ok,[string]$msg){if(-not $ok){throw $msg}}
function WriteCreate([string]$p,[object]$v){$s=[IO.File]::Open($p,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$b=[Text.UTF8Encoding]::new($false).GetBytes(($v|ConvertTo-Json -Depth 20)+"`n");$s.Write($b,0,$b.Length);$s.Flush($true)}finally{$s.Dispose()}}
function LauncherTree([string]$Root){
  $rootFull=[IO.Path]::GetFullPath($Root);$relative=[Collections.Generic.List[string]]::new();foreach($file in Get-ChildItem -LiteralPath $rootFull -Recurse -File -Force){$r=[IO.Path]::GetRelativePath($rootFull,$file.FullName).Replace('\','/');if(("/$r/") -match '/__pycache__/' -or $r.EndsWith('.pyc',[StringComparison]::OrdinalIgnoreCase)){continue};[void]$relative.Add($r)};$relative.Sort([StringComparer]::Ordinal);$manifest=[Text.StringBuilder]::new();foreach($r in $relative){$f=Join-Path $rootFull $r.Replace('/',[IO.Path]::DirectorySeparatorChar);[void]$manifest.Append($r).Append("`t").Append((Hash $f)).Append("`n")};$h=[Security.Cryptography.SHA256]::Create();try{$sha=([BitConverter]::ToString($h.ComputeHash([Text.UTF8Encoding]::new($false).GetBytes($manifest.ToString())))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()};[pscustomobject]@{sha256=$sha;file_count=$relative.Count}
}
